// Public input reaches a spreadsheet. A value starting with = + - or @
// would be run by Google Sheets as a formula, so it is prefixed with an
// invisible zero-width space and always stored as plain text.
function safeItems(items) {
  return items.map(function (it) {
    var o = {};
    Object.keys(it.json).forEach(function (k) {
      var v = it.json[k];
      o[k] = (typeof v === 'string' && /^[=+\-@\t\r]/.test(v)) ? '\u200B' + v : v;
    });
    return { json: o };
  });
}

// ═══════════════════════════════════════════════════════
//  Normalise Allergens
//  The picker already returns clean values. The optional
//  free-text box does not, so everything still goes through
//  the same alias table before it is stored.
//
//  If the signup vocabulary and the recall vocabulary ever
//  drift apart, a registered user is silently never alerted.
//  That is why both sides share these exact eleven names.
// ═══════════════════════════════════════════════════════

const CANON = {
  'peanuts':      ['peanut', 'peanuts', 'arachis', 'groundnut', 'groundnuts'],
  'tree nuts':    ['tree nut', 'tree nuts', 'treenut', 'treenuts', 'nut', 'nuts',
                   'almond', 'almonds', 'cashew', 'cashews', 'walnut', 'walnuts',
                   'pecan', 'pecans', 'pistachio', 'pistachios', 'macadamia',
                   'macadamias', 'hazelnut', 'hazelnuts', 'brazil nut', 'brazil nuts'],
  'milk':         ['milk', 'dairy', 'lactose', 'casein', 'whey', 'ghee', 'cheese', 'butter'],
  'egg':          ['egg', 'eggs', 'albumen', 'ovalbumin'],
  'sesame':       ['sesame', 'tahini', 'sesame seed', 'sesame seeds'],
  'soy':          ['soy', 'soya', 'soybean', 'soybeans', 'tofu'],
  'wheat/gluten': ['wheat', 'gluten', 'wheat gluten', 'coeliac', 'celiac',
                   'semolina', 'durum', 'spelt', 'farina', 'barley', 'rye'],
  'fish':         ['fish', 'salmon', 'tuna', 'cod', 'anchovy', 'anchovies'],
  'shellfish':    ['shellfish', 'crustacean', 'crustaceans', 'prawn', 'prawns',
                   'shrimp', 'shrimps', 'crab', 'crabs', 'lobster', 'lobsters',
                   'mollusc', 'molluscs', 'oyster', 'oysters', 'mussel', 'mussels',
                   'squid', 'scallop', 'scallops'],
  'lupin':        ['lupin', 'lupins', 'lupine'],
  'sulphites':    ['sulphite', 'sulphites', 'sulfite', 'sulfites']
};

// Form keys can be the short name or the full question label.
function pick(obj, keys) {
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

const j = $json;

const name     = String(pick(j, ['name', 'Name'])).trim();
const email    = String(pick(j, ['email', 'Email'])).trim().toLowerCase();
const postcode = String(pick(j, ['postcode', 'Suburb or postcode (optional)', 'suburb'])).trim();
const rawSev   = String(pick(j, ['severity', 'How severe is your reaction?',
                                 'How severe? (anaphylaxis / severe / mild)'])).trim().toLowerCase();

// Collect every allergy field by pattern, so the picker and the
// free-text box are both read no matter how they are labelled.
const allergyKeys = Object.keys(j).filter(function (k) { return /allerg/i.test(k); });
let picked = [];
for (const k of allergyKeys) {
  const v = j[k];
  if (Array.isArray(v)) picked = picked.concat(v);
  else if (String(v || '').trim()) picked = picked.concat(String(v).split(/[,;/]|\band\b/i));
}
const typed = '';

// The picker gives an array (or a comma string when only one is chosen).
let entries = [];
if (Array.isArray(picked)) entries = entries.concat(picked);
else if (String(picked).trim()) entries = entries.concat(String(picked).split(/[,;]/));
if (String(typed).trim()) entries = entries.concat(String(typed).split(/[,;/]|\band\b/i));

const normalised = [];
const unrecognised = [];

for (const entry of entries) {
  const token = String(entry).trim().toLowerCase().replace(/[^a-z\s/]/g, '').trim();
  if (!token) continue;

  let matchedTo = '';
  if (CANON[token]) matchedTo = token;                       // already canonical
  if (!matchedTo) {
    for (const canon of Object.keys(CANON)) {
      if (CANON[canon].indexOf(token) !== -1) { matchedTo = canon; break; }
    }
  }
  if (!matchedTo) {                                          // "peanut allergy" etc
    for (const canon of Object.keys(CANON)) {
      if (CANON[canon].some(function (a) { return token.indexOf(a) !== -1; })) {
        matchedTo = canon; break;
      }
    }
  }

  if (matchedTo) {
    if (normalised.indexOf(matchedTo) === -1) normalised.push(matchedTo);
  } else {
    unrecognised.push(token);
  }
}

// Default to severe when not stated. Erring on the safe side.
let severity = 'severe';
if (rawSev.indexOf('anaphyla') !== -1) severity = 'anaphylaxis';
else if (rawSev.indexOf('mild') !== -1) severity = 'mild';

// Injector and medicines feed the TGA shortage monitor
// and the expiry reminder. Registering a brand means we also
// alert on a shortage of that drug under any brand.
const injector = String(pick(j, ['Adrenaline autoinjector you carry (optional)',
                                 'injector_type'])).trim();
const expiry   = String(pick(j, ['Injector expiry date (optional)',
                                 'injector_expiry'])).trim();
const otherMed = String(pick(j, ['Other medicines you depend on (optional)',
                                 'medicines'])).trim();

const meds = [];
if (injector && injector.toLowerCase() !== 'none') meds.push(injector.toLowerCase());
otherMed.split(/[,;]/).forEach(function (m) {
  const t = m.trim().toLowerCase();
  if (t && meds.indexOf(t) === -1) meds.push(t);
});

const userId = 'usr_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);

console.log(email + ' -> ' + normalised.join(', ') + ' [' + severity + ']' +
            (unrecognised.length ? ' | not recognised: ' + unrecognised.join(', ') : ''));

return safeItems([{
  json: {
    user_id:             userId,
    name:                name,
    email:               email,
    postcode:            postcode,
    allergens:           normalised.join(','),
    allergens_display:   normalised.join(', '),
    unrecognised:        unrecognised.join(', '),
    severity:            severity,
    injector_type:       (injector && injector.toLowerCase() !== 'none') ? injector : '',
    injector_expiry:     expiry,
    medicines:           meds.join(','),
    dietary_preferences: '',
    created_at:          new Date().toISOString()
  }
}]);

// The profile could not be saved. This is the one failure the
// user must be protected from, because they would otherwise
// believe they are covered when they are not.
return [{
  json: {
    timestamp:     new Date().toISOString(),
    node_name:     'Store Profile',
    error_message: 'Could not write profile to the users sheet: ' + String($json.error || 'unknown error'),
    severity:      'critical'
  }
}];

// Explain the rejection in terms the operator can act on.
// Fields are scanned by pattern, not by exact label.
const j = $json;
const email = String(j.email || j.Email || '').trim();
const allerg = Object.keys(j)
  .filter(function (k) { return /allerg/i.test(k); })
  .map(function (k) { return Array.isArray(j[k]) ? j[k].join(',') : String(j[k] || ''); })
  .filter(function (v) { return v.trim(); })
  .join(',');

const reasons = [];
if (!email) reasons.push('missing email');
else if (email.indexOf('@') === -1) reasons.push('malformed email');
if (!allerg) reasons.push('no allergens given');

return [{ json: {
  timestamp:     new Date().toISOString(),
  node_name:     'Validate Submission',
  error_message: 'Rejected signup: ' + (reasons.join('; ') || 'unknown') +
                 ' | fields: ' + Object.keys(j).join(', '),
  severity:      'warning'
}}];

// ═══════════════════════════════════════════════════════
//  Extract Allergens
//  Deterministic parsing. No LLM by design: the notices
//  have a fixed structure, so string matching is more
//  accurate, costs nothing, and cannot fail mid-demo.
// ═══════════════════════════════════════════════════════

// Same eleven canonical names the signup form produces.
// The arrays are the names an allergen hides behind on a
// label — casein is milk, arachis is peanut. Without these
// we would tell a milk-allergic user a casein product is
// unrelated to them.
const ALLERGENS = {
  'peanuts':      ['peanut', 'arachis', 'groundnut'],
  'tree nuts':    ['tree nut', 'almond', 'cashew', 'walnut', 'pecan', 'pistachio', 'macadamia', 'hazelnut', 'brazil nut'],
  'milk':         ['milk', 'dairy', 'casein', 'whey', 'lactose', 'ghee'],
  'egg':          ['egg', 'albumen'],
  'soy':          ['soy', 'soya', 'soybean'],
  'wheat/gluten': ['wheat', 'gluten', 'semolina', 'durum', 'spelt', 'farina'],
  'sesame':       ['sesame', 'tahini'],
  'fish':         ['fish'],
  'shellfish':    ['shellfish', 'crustacean', 'prawn', 'shrimp', 'crab', 'lobster', 'mollusc'],
  'lupin':        ['lupin'],
  'sulphites':    ['sulphite', 'sulfite']
};

const results = [];

for (const item of $input.all()) {
  const d = item.json;

  // contentSnippet is the clean plain-text version.
  // Never use `content` — that field is raw HTML.
  const snippet = String(d.contentSnippet || '').replace(/\s+/g, ' ');

  // Every notice follows the same structure:
  //   Problem: ... / Food safety hazard: ... / What to do: ...
  const m = snippet.match(/Problem:?\s*(.*?)(?=Food safety hazard|Food Safety Hazard|What to do)/i);
  const problem = m ? m[1].trim() : snippet;

  // Recalls also happen for metal, mould and Listeria.
  // Only undeclared-allergen recalls concern us.
  const isAllergenRecall = /undeclared allergen/i.test(problem);

  // Collect EVERY allergen named, not just the first.
  // One recall often lists three, e.g. egg, milk and soy.
  const found = [];
  if (isAllergenRecall) {
    for (const allergen of Object.keys(ALLERGENS)) {
      const aliases = ALLERGENS[allergen];
      const hit = aliases.some(function (alias) {
        // Word boundaries so "veggie" never matches "egg".
        return new RegExp('\\b' + alias + 's?\\b', 'i').test(problem);
      });
      if (hit) found.push(allergen);
    }
  }

  // Titles look like "Brand Pty Ltd - Product - 200g",
  // sometimes prefixed with "UPDATED 02.09.26 | ".
  const title = String(d.title || '').trim();
  const brand = title.replace(/^UPDATED.*?\|\s*/i, '').split(' - ')[0].trim();

  // Best-before info tells a user whether THEIR pack is affected.
  const dm = snippet.match(/Date [Mm]arking:?\s*(.*?)(?=Problem|Batch|$)/);

  results.push({
    json: {
      guid:               d.guid,
      title:              title,
      brand:              brand,
      link:               d.link,
      published:          d.isoDate,
      problem:            problem,
      is_allergen_recall: isAllergenRecall,
      allergens:          found,
      allergen_list:      found.join(','),
      date_marking:       dm ? dm[1].trim() : '',
      processed_at:       new Date().toISOString()
    }
  });
}

const allergenCount = results.filter(function (r) { return r.json.is_allergen_recall; }).length;
console.log(results.length + ' recalls parsed, ' + allergenCount + ' caused by an undeclared allergen');

return results;

// ═══════════════════════════════════════════════════════
//  Skip Already Processed
//  Drops any recall whose guid is already in the sheet, so
//  nobody is ever alerted twice for the same recall.
// ═══════════════════════════════════════════════════════

// Every guid we have handled before.
// Blank rows are ignored so an empty sheet still works.
const seen = new Set(
  $('Get Processed Recalls').all()
    .map(function (r) { return String((r.json && r.json.guid) || '').trim(); })
    .filter(function (g) { return g.length > 0; })
);

const fresh = [];

for (const item of $input.all()) {
  const guid = String(item.json.guid || '').trim();
  if (seen.has(guid)) continue;
  fresh.push(item);
}

console.log(seen.size + ' already processed, ' + fresh.length + ' new');

return fresh;

// ═══════════════════════════════════════════════════════
//  Match Users To Recalls
//  One output item per (user x matching recall).
//  A user with no overlapping allergen produces NOTHING.
//  That silence is the product.
// ═══════════════════════════════════════════════════════

function toArray(v) {
  if (Array.isArray(v)) return v;
  const s = String(v || '').trim();
  if (!s) return [];
  if (s.charAt(0) === '[') {
    try { const p = JSON.parse(s); if (Array.isArray(p)) return p; } catch (e) {}
  }
  return s.split(',');
}

// ── Live profiles ───────────────────────────────────────────
// Filling the form again is how a person updates their allergies,
// so the NEWEST row per (email + name) is the one that counts.
// Keying on name as well lets a parent register each child under
// their own address as a separate person.
// An unsubscribe only counts if it is newer than that email's latest
// signup — so somebody who comes back is actually back.
function liveProfiles(userItems, unsubItems) {
  const latest = {};
  const lastSignup = {};
  userItems.forEach(function (it) {
    const u = it && it.json;
    if (!u || !u.email || String(u.email).indexOf('@') === -1) return;
    const email = String(u.email).trim().toLowerCase();
    const key = email + '|' + String(u.name || '').trim().toLowerCase();
    const t = Date.parse(String(u.created_at || '')) || 0;
    if (!latest[key] || t >= latest[key].t) latest[key] = { t: t, u: u };
    if (!lastSignup[email] || t > lastSignup[email]) lastSignup[email] = t;
  });
  const optOut = {};
  (unsubItems || []).forEach(function (it) {
    const r = it && it.json;
    if (!r || !r.email) return;
    const email = String(r.email).trim().toLowerCase();
    const t = Date.parse(String(r.unsubscribed_at || '')) || Date.now();
    if (!optOut[email] || t > optOut[email]) optOut[email] = t;
  });
  return Object.keys(latest).map(function (k) { return latest[k].u; })
    .filter(function (u) {
      const email = String(u.email).trim().toLowerCase();
      return !(optOut[email] && optOut[email] > (lastSignup[email] || 0));
    });
}

// New allergen recalls that survived deduplication.
const recalls = $('Skip Already Processed').all()
  .map(function (i) { return i.json; })
  .filter(function (r) {
    return r && r.is_allergen_recall === true &&
           Array.isArray(r.allergens) && r.allergens.length > 0;
  });

// How many undeclared-allergen recalls has each brand had before?
// Nobody publishes this, not even the regulator. A brand that
// appears repeatedly is a pattern, not an accident.
const brandHistory = {};
$('Get Processed Recalls').all().forEach(function (r) {
  const b = String((r.json && r.json.brand) || '').trim().toLowerCase();
  if (b) brandHistory[b] = (brandHistory[b] || 0) + 1;
});

const users = liveProfiles($('Get Users').all(), $('Get Unsubscribes').all());

const out = [];

for (const recall of recalls) {
  const recallAllergens = recall.allergens.map(function (a) {
    return String(a).trim().toLowerCase();
  });

  const brandKey = String(recall.brand || '').trim().toLowerCase();
  const priorRecalls = (brandHistory[brandKey] || 0);

  for (const user of users) {
    const userAllergens = toArray(user.allergens)
      .map(function (a) { return String(a).trim().toLowerCase(); })
      .filter(Boolean);

    const matched = userAllergens.filter(function (a) {
      return recallAllergens.indexOf(a) !== -1;
    });

    // No overlap -> this user hears nothing. Deliberate.
    if (matched.length === 0) continue;

    const sev = String(user.severity || 'severe').trim().toLowerCase();

    out.push({
      json: {
        name:              user.name || '',
        email:             String(user.email).trim(),
        severity:          (sev === 'anaphylaxis' || sev === 'mild') ? sev : 'severe',
        matched_allergens: matched.join(', '),
        product:           recall.title,
        brand:             recall.brand,
        all_allergens:     recall.allergen_list,
        date_marking:      recall.date_marking,
        link:              recall.link,
        evidence:          recall.problem,
        recall_guid:       recall.guid,
        prior_recalls:     priorRecalls,
        repeat_warning:    priorRecalls >= 2
          ? 'This brand has had ' + (priorRecalls + 1) +
            ' undeclared-allergen recalls in our records.'
          : '',
        channel:           'email',
        sent_at:           new Date().toISOString()
      }
    });
  }
}

console.log(recalls.length + ' new allergen recalls x ' + users.length +
            ' live profiles = ' + out.length + ' alerts');

return out;

// ═══════════════════════════════════════════════════════
//  Feed Health Check
//
//  For a safety system the most dangerous failure is not an
//  error. It is silence. A user who receives no alerts
//  assumes they are safe. If our feed quietly stopped
//  working three weeks ago, they would never know.
//
//  So we monitor our own monitoring.
// ═══════════════════════════════════════════════════════

const STALE_HOURS = 48;

// Only FSANZ recall rows count. TGA shortage rows live in the same
// tab, and counting them would let a dead recall feed look healthy
// just because the medicine monitor is still running — which is the
// precise failure this watchdog exists to catch.
const rows = $input.all()
  .map(function (i) { return i.json; })
  .filter(function (r) {
    return r && Object.keys(r).length > 0 && r.processed_at &&
           String(r.source || '').toLowerCase() !== 'tga';
  });

let lastSeenMs = null;

for (const row of rows) {
  const t = Date.parse(String(row.processed_at));
  if (!isNaN(t) && (lastSeenMs === null || t > lastSeenMs)) lastSeenMs = t;
}

// Never run at all, or the history was cleared.
if (lastSeenMs === null) {
  return [{
    json: {
      healthy:       false,
      hours_silent:  null,
      last_seen:     'never',
      total_recalls: rows.length,
      message:       'The recall monitor has no record of ever processing a recall. Either it has never run, or the history was cleared.',
      checked_at:    new Date().toISOString()
    }
  }];
}

const hoursSilent = Math.round(((Date.now() - lastSeenMs) / 3600000) * 10) / 10;
const healthy = hoursSilent <= STALE_HOURS;

console.log('Last processed ' + hoursSilent + ' hours ago. Healthy: ' + healthy);

return [{
  json: {
    healthy:       healthy,
    hours_silent:  hoursSilent,
    last_seen:     new Date(lastSeenMs).toISOString(),
    total_recalls: rows.length,
    message: healthy
      ? 'Recall monitor is healthy. Last processed ' + hoursSilent + ' hours ago.'
      : 'Recall monitor has processed nothing for ' + hoursSilent + ' hours. Users may believe they are protected when they are not.',
    checked_at:    new Date().toISOString()
  }
}];

// One log row per alert actually sent. Runs once per item.
let m;
try { m = $('Match Users To Recalls').item.json; }
catch (e) { m = $('Match Users To Recalls').first().json; }

return { json: {
  sent_at:           m.sent_at,
  user_email:        m.email,
  product:           m.product,
  matched_allergens: m.matched_allergens,
  channel:           'email',
  status:            'sent',
  recall_guid:       m.recall_guid
}};

// The alert did not go out. Record it rather than lose it.
let m;
try { m = $('Match Users To Recalls').item.json; }
catch (e) { m = $('Match Users To Recalls').first().json; }

return { json: {
  sent_at:           new Date().toISOString(),
  user_email:        m.email,
  product:           m.product,
  matched_allergens: m.matched_allergens,
  channel:           'email',
  status:            'failed: ' + String($json.error || 'delivery error'),
  recall_guid:       m.recall_guid
}};

// The government feed could not be reached after 3 retries.
return [{ json: {
  timestamp:      new Date().toISOString(),
  node_name:      'RSS Read',
  error_message:  String($json.error || 'Government recall feed unreachable after 3 retries'),
  severity:       'critical'
}}];

// The monitor has gone quiet for too long.
const h = $('Check Feed Health').first().json;
return [{ json: {
  timestamp:      h.checked_at,
  node_name:      'Feed Watchdog',
  error_message:  h.message,
  severity:       'critical'
}}];

// Public input reaches a spreadsheet. A value starting with = + - or @
// would be run by Google Sheets as a formula, so it is prefixed with an
// invisible zero-width space and always stored as plain text.
function safeItems(items) {
  return items.map(function (it) {
    var o = {};
    Object.keys(it.json).forEach(function (k) {
      var v = it.json[k];
      o[k] = (typeof v === 'string' && /^[=+\-@\t\r]/.test(v)) ? '\u200B' + v : v;
    });
    return { json: o };
  });
}

// Same email, typed differently, is still the same person.
const j = $json;
const email = String(j.email || j.Email || '').trim().toLowerCase();

return safeItems([{ json: {
  email:          email,
  unsubscribed_at: new Date().toISOString(),
  source:         'web form'
}}]);

// Public input reaches a spreadsheet. A value starting with = + - or @
// would be run by Google Sheets as a formula, so it is prefixed with an
// invisible zero-width space and always stored as plain text.
function safeItems(items) {
  return items.map(function (it) {
    var o = {};
    Object.keys(it.json).forEach(function (k) {
      var v = it.json[k];
      o[k] = (typeof v === 'string' && /^[=+\-@\t\r]/.test(v)) ? '\u200B' + v : v;
    });
    return { json: o };
  });
}

// ═══════════════════════════════════════════════════════
//  Prepare Listing
//  Restaurants describe their kitchen in their own words.
//  We store the declaration exactly as given, but the
//  allergen list goes through the same eleven canonical
//  names the recall side uses — otherwise a diner filtering
//  for "milk" would never see a venue that wrote "dairy".
// ═══════════════════════════════════════════════════════

const CANON = ['peanuts', 'tree nuts', 'milk', 'egg', 'soy', 'wheat/gluten',
               'sesame', 'fish', 'shellfish', 'lupin', 'sulphites'];

function pick(obj, keys) {
  for (const k of keys) {
    const v = obj[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

const j = $json;

const name    = String(pick(j, ['Restaurant name', 'restaurant_name', 'name'])).trim();
const suburb  = String(pick(j, ['Suburb', 'suburb'])).trim();
const cuisine = String(pick(j, ['Cuisine', 'cuisine'])).trim();
const prep    = String(pick(j, ['Do you have a separate preparation area for allergen-free orders?',
                                'prep_area'])).trim();
const notes   = String(pick(j, ['Anything a diner should know', 'notes'])).trim();
const email   = String(pick(j, ['Contact email', 'contact_email', 'email'])).trim().toLowerCase();

const rawAll = pick(j, ['Which allergens can your kitchen accommodate on request?',
                        'allergens_accommodated', 'allergens']);

let entries = Array.isArray(rawAll) ? rawAll : String(rawAll).split(/[,;]/);
const accommodated = [];
for (const e of entries) {
  const t = String(e).trim().toLowerCase();
  if (CANON.indexOf(t) !== -1 && accommodated.indexOf(t) === -1) accommodated.push(t);
}

// A dedicated prep area is the single biggest factor in
// cross-contamination risk, so it is stored as its own field
// rather than buried in free text.
let crossContam = 'unknown';
if (prep.indexOf('dedicated') !== -1) crossContam = 'dedicated area';
else if (prep.indexOf('shared') !== -1) crossContam = 'shared area, cleaned between orders';
else if (prep === 'no') crossContam = 'no separate area';

const id = 'res_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

return safeItems([{ json: {
  restaurant_id:          id,
  name:                   name,
  suburb:                 suburb,
  cuisine:                cuisine,
  allergens_accommodated: accommodated.join(','),
