    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const haystack = (title + ' ' + summary).toLowerCase();

  const isInjector = INJECTOR.some(function (w) { return haystack.indexOf(w) !== -1; });

  // Resolved shortages are good news, not an alert.
  const resolving = /resolv|resolved|has ended/i.test(title);

  results.push({
    json: {
      guid:          String(d.guid || d.link || title),
      source:        'tga',
      title:         title,
      brand:         'TGA medicine shortage',
      summary:       summary,
      haystack:      haystack,
      link:          d.link,
      published:     d.isoDate || d.pubDate,
      is_injector:   isInjector,
      resolving:     resolving,
