//  A user tells us what they carry or take. We tell them when
//  the regulator says it is running out — and only then.
// ═══════════════════════════════════════════════════════

const INJECTOR_WORDS = ['epipen', 'anapen', 'adrenaline', 'epinephrine',
                        'auto-injector', 'autoinjector', 'auto injector'];

// ── Live profiles ───────────────────────────────────────────
// Filling the form again is how a person updates their allergies,
// so the NEWEST row per (email + name) is the one that counts.
// Keying on name as well lets a parent register each child under
// their own address as a separate person.
// An unsubscribe only counts if it is newer than that email's latest
// signup — so somebody who comes back is actually back.
function liveProfiles(userItems, unsubItems) {
  const latest = {};
  const lastSignup = {};
  userItems.forEach(function (it) {
    const u = it && it.json;
    if (!u || !u.email || String(u.email).indexOf('@') === -1) return;
    const email = String(u.email).trim().toLowerCase();
    const key = email + '|' + String(u.name || '').trim().toLowerCase();
    const t = Date.parse(String(u.created_at || '')) || 0;
    if (!latest[key] || t >= latest[key].t) latest[key] = { t: t, u: u };
    if (!lastSignup[email] || t > lastSignup[email]) lastSignup[email] = t;
  });
  const optOut = {};
  (unsubItems || []).forEach(function (it) {
    const r = it && it.json;
    if (!r || !r.email) return;
    const email = String(r.email).trim().toLowerCase();
    const t = Date.parse(String(r.unsubscribed_at || '')) || Date.now();
    if (!optOut[email] || t > optOut[email]) optOut[email] = t;
  });
  return Object.keys(latest).map(function (k) { return latest[k].u; })
    .filter(function (u) {
      const email = String(u.email).trim().toLowerCase();
      return !(optOut[email] && optOut[email] > (lastSignup[email] || 0));
    });
}

const alerts = $('Skip Processed Shortages').all()
  .map(function (i) { return i.json; })
  .filter(function (a) { return a && a.title && !a.resolving; });

const users = liveProfiles($('Get Users For Medicines').all(),
                           $('Get Unsubscribes For Medicines').all());

const out = [];

for (const alert of alerts) {
  for (const user of users) {
    const listed = String(user.medicines || '')
      .split(',').map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean);

    if (!listed.length) continue;

    const matched = [];
    for (const med of listed) {
      // A brand name matching the alert text is a direct hit.
      if (alert.haystack.indexOf(med) !== -1) { matched.push(med); continue; }
      // Someone who registered "EpiPen" still wants to hear about
      // an adrenaline autoinjector shortage under any brand.
      const userCarriesInjector = INJECTOR_WORDS.some(function (w) {
        return med.indexOf(w) !== -1;
      });
      if (userCarriesInjector && alert.is_injector) matched.push(med);
    }

    if (!matched.length) continue;

    out.push({
      json: {
        name:      user.name || '',
        email:     String(user.email).trim(),
        matched:   matched.join(', '),
        title:     alert.title,
        summary:   alert.summary,
        link:      alert.link,
        guid:      alert.guid,
        injector:  alert.is_injector === true,
        sent_at:   new Date().toISOString()
      }
    });
  }
}

