const SPEAK_AT = [90, 60, 30, 7, 0];

const out = [];
const today = new Date();
today.setHours(0, 0, 0, 0);

const people = liveProfiles($('Get Users For Expiry').all(), $('Get Unsubscribes For Expiry').all());

for (const u of people) {

  const raw = String(u.injector_expiry || '').trim();
  if (!raw) continue;

  // Accept 2027-04, 2027-04-30, 30/04/2027 and April 2027.
  let d = null;
  let m = raw.match(/^(\d{4})-(\d{1,2})(?:-(\d{1,2}))?$/);
  if (m) d = new Date(+m[1], +m[2] - 1, m[3] ? +m[3] : 28);
  if (!d) {
    m = raw.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
    if (m) d = new Date(+m[3], +m[2] - 1, +m[1]);
  }
  if (!d) { const p = Date.parse(raw); if (!isNaN(p)) d = new Date(p); }
  if (!d || isNaN(d.getTime())) continue;

  d.setHours(0, 0, 0, 0);
  const days = Math.round((d - today) / 86400000);

  const speak = SPEAK_AT.indexOf(days) !== -1 || days < 0;
  if (!speak) continue;

  // Past the date we say it once, not every day forever.
  if (days < 0 && days !== -1) continue;

  out.push({
    json: {
      name:         u.name || '',
      email:        String(u.email).trim(),
      device:       String(u.injector_type || 'adrenaline autoinjector').trim(),
      expiry:       raw,
      days_left:    days,
      expired:      days < 0,
      urgency:      days < 0 ? 'expired' : (days <= 7 ? 'urgent' : (days <= 30 ? 'soon' : 'planning')),
      sent_at:      new Date().toISOString()
    }
  });
}

