  }
  return '';
}
function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}
function isEmail(s) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || '').trim()); }

const senderName  = String(pick(['Your name'])).trim() || 'A parent';
const senderEmail = String(pick(['Your email'])).trim().toLowerCase();
