if (!Array.isArray(list)) list = [];

const SEV = { anaphylaxis: 'Anaphylaxis risk (life-threatening)', severe: 'Severe reaction', mild: 'Mild reaction' };
const profiles = list.map(function (p) {
  p = p || {};
  const allergens = (Array.isArray(p.allergens) ? p.allergens : String(p.allergens || '').split(','))
    .map(function (a) { return String(a).trim().toLowerCase(); })
    .filter(function (a, i, arr) { return CANON.indexOf(a) !== -1 && arr.indexOf(a) === i; });
  const sev = String(p.severity || '').toLowerCase();
  return {
    name:      String(p.name || '').trim().slice(0, 80),
    relation:  String(p.relation || '').trim().slice(0, 40),
    allergens: allergens,
    severity:  SEV[sev] ? sev : 'severe',
    injector:  String(p.injector || '').trim().slice(0, 40),
    notes:     String(p.notes || '').trim().slice(0, 300)
